select *
from ( select row_.*, rownum rownum_ from ( select project_code, project_reportname, institution_code, project_name, type_name, administrative_levelname, application_provincename, addressname, nconstructionarea, state_name, pk_project, ordermethod, planmodel, planpriority, pk_group, pk_org, pk_workcalendar, pk_projectclass, application_province200, administrative_level from ( select * from ( select distinct institution_code, PROJECT_name, PROJECT_CODE, bd_project.pk_project, bd_project.ordermethod ordermethod, bd_project.planmodel planmodel, bd_project.planpriority planpriority, bd_project.pk_group pk_group, bd_project.pk_org pk_org, bd_project.pk_workcalendar pk_workcalendar, bd_project.pk_projectclass pk_projectclass, application_province200, administrative_level, project_reportname, type_name, e.name administrative_levelname, d.name application_provincename, r.name addressname, bd_project.pk_projectstate, pk_duty_org, bd_project.dr dr, bd_project.pk_eps, bd_project.def1 nconstructionarea, e.state_name state_name from bd_project left outer join bd_region r on r.pk_region = bd_project.address left outer join bd_projectclass p on p.pk_projectclass = bd_project.pk_projectclass left outer join md_enumvalue e on e.value = bd_project.administrative_level and e.id = '1d0dbab7-07af-48d9-94f5-70bdb0e944b5' left outer join bd_defdoc d on d.PK_DEFDOC = bd_project.application_province200 left outer join pm_projectstate e on bd_project.pk_projectstate = e.pk_projectstate where bd_project.enablestate = 2 and bd_project.administrative_level not in ( '5', '6' ) ) ) where 11 = 11 and pk_project in ( select pk_project from pim_set_information_h where nvl ( dr, 0 ) = 0 and ctrantypeid = '1001A810000001UJ5S79' and fstatusflag = 1 ) and ( pk_projectstate <> '~' and pk_projectstate is not null and pk_duty_org = '0001U110000000000VBF' ) and ( pk_eps = '1001A110000000FBCHC0' ) order by project_code ) row_ where rownum <= 500 )
where rownum_ > 0
